func lowestCommonAncestor(root *TreeNode, p *TreeNode, q *TreeNode) *TreeNode {
	if root == nil || root == p || root == q {
		return root
	}
	left := lowestCommonAncestor(root.Left, p, q)
	right := lowestCommonAncestor(root.Right, p, q)
	if left != nil && right != nil {
		return root
	}
	if left != nil {
		return left
	}
	return right
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
    if (root == null || root == p || root == q) return root;
    TreeNode left = lowestCommonAncestor(root.left, p, q);
    TreeNode right = lowestCommonAncestor(root.right, p, q);
    if (left != null && right != null) return root;
    return left != null ? left : right;
  }
}

class Solution:
    def lowestCommonAncestor(self, root: TreeNode, p: TreeNode, q: TreeNode) -> Optional[TreeNode]:
        if root is None or root is p or root is q:
            return root
        left = self.lowestCommonAncestor(root.left, p, q)
        right = self.lowestCommonAncestor(root.right, p, q)
        if left and right:
            return root
        return left if left else right

impl Solution {
  pub fn lowest_common_ancestor(
    root: &Option<Box<TreeNode>>,
    p: i32,
    q: i32,
  ) -> Option<i32> {
    fn walk(node: &Option<Box<TreeNode>>, p: i32, q: i32) -> Option<(i32, bool, bool)> {
      if let Some(n) = node {
        let mut has_p = n.val == p;
        let mut has_q = n.val == q;
        if let Some((v, hp, hq)) = walk(&n.left, p, q) {
          if hp && hq {
            return Some((v, true, true));
          }
          has_p |= hp;
          has_q |= hq;
        }
        if let Some((v, hp, hq)) = walk(&n.right, p, q) {
          if hp && hq {
            return Some((v, true, true));
          }
          has_p |= hp;
          has_q |= hq;
        }
        if has_p && has_q {
          return Some((n.val, true, true));
        }
        return Some((0, has_p, has_q));
      }
      None
    }
    walk(root, p, q).map(|(v, _, _)| v)
  }
}

const lowestCommonAncestor = (root: TreeNode | null, p: TreeNode, q: TreeNode): TreeNode | null => {
  if (!root || root === p || root === q) return root;
  const left = lowestCommonAncestor(root.left, p, q);
  const right = lowestCommonAncestor(root.right, p, q);
  if (left && right) return root;
  return left ? left : right;
};
